import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import {
  CheckIcon,
  XCircleIcon,
  ChevronDownIcon,
  XIcon,
  WandSparklesIcon,
} from "lucide-react";

import { cn } from "@/lib/utils";
import { Separator } from "@/components/ui/separator";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
} from "@/components/ui/command";

/**
 * Variants for the multi-select component to handle different styles.
 * Uses class-variance-authority (cva) to define different styles based on "variant" prop.
 */
const multiSelectVariants = cva("m-1", {
  variants: {
    variant: {
      default: "border-foreground/10 text-foreground bg-card hover:bg-card/80",
      secondary:
        "border-foreground/10 bg-secondary text-secondary-foreground hover:bg-secondary/80",
      destructive:
        "border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
      inverted: "inverted",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

/**
 * Props for MultiSelect component
 */
interface MultiSelectProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof multiSelectVariants> {
  /**
   * An array of option objects to be displayed in the multi-select component.
   * Each option object has a label, value, and an optional icon.
   */
  options: {
    /** The text to display for the option. */
    label: string;
    /** The unique value associated with the option. */
    value: string;
    /** Optional icon component to display alongside the option. */
    icon?: React.ComponentType<{ className?: string }>;
  }[];

  /**
   * Callback function triggered when the selected values change.
   * Receives an array of the new selected values.
   */
  onValueChange: (value: string[]) => void;

  /** The default selected values when the component mounts. */
  defaultValue?: string[];

  /**
   * Placeholder text to be displayed when no values are selected.
   * Optional, defaults to "Select options".
   */
  placeholder?: string;

  /**
   * Animation duration in seconds for the visual effects (e.g., bouncing badges).
   * Optional, defaults to 0 (no animation).
   */
  animation?: number;

  /**
   * Maximum number of items to display. Extra selected items will be summarized.
   * Optional, defaults to 3.
   */
  maxCount?: number;

  /**
   * The modality of the popover. When set to true, interaction with outside elements
   * will be disabled and only popover content will be visible to screen readers.
   * Optional, defaults to false.
   */
  modalPopover?: boolean;

  /**
   * If true, renders the multi-select component as a child of another component.
   * Optional, defaults to false.
   */
  asChild?: boolean;

  /**
   * Additional class names to apply custom styles to the multi-select component.
   * Optional, can be used to add custom styles.
   */
  className?: string;
}

export const MultiSelect = React.forwardRef<
  HTMLButtonElement,
  MultiSelectProps
>(
  (
    {
      options,
      onValueChange,
      variant,
      defaultValue = [],
      placeholder = "Select options",
      animation = 0,
      maxCount = 3,
      modalPopover = false,
      className,
      ...props
    },
    ref
  ) => {
    const [selectedValues, setSelectedValues] =
      React.useState<string[]>(defaultValue);
    const [isPopoverOpen, setIsPopoverOpen] = React.useState(false);
    const [isAnimating, setIsAnimating] = React.useState(false);

    const handleInputKeyDown = (
      event: React.KeyboardEvent<HTMLInputElement>
    ) => {
      if (event.key === "Enter") {
        setIsPopoverOpen(true);
      } else if (event.key === "Backspace" && !event.currentTarget.value) {
        const newSelectedValues = [...selectedValues];
        newSelectedValues.pop();
        setSelectedValues(newSelectedValues);
        onValueChange(newSelectedValues);
      }
    };

    const toggleOption = (option: string) => {
      const newSelectedValues = selectedValues.includes(option)
        ? selectedValues.filter((value) => value !== option)
        : [...selectedValues, option];
      setSelectedValues(newSelectedValues);
      onValueChange(newSelectedValues);
    };

    const handleClear = () => {
      setSelectedValues([]);
      onValueChange([]);
    };

    const handleTogglePopover = () => {
      setIsPopoverOpen((prev) => !prev);
    };

    const clearExtraOptions = () => {
      const newSelectedValues = selectedValues.slice(0, maxCount);
      setSelectedValues(newSelectedValues);
      onValueChange(newSelectedValues);
    };

    const toggleAll = () => {
      if (selectedValues.length === options.length) {
        handleClear();
      } else {
        const allValues = options.map((option) => option.value);
        setSelectedValues(allValues);
        onValueChange(allValues);
      }
    };

    return (
      <Popover
        open={isPopoverOpen}
        onOpenChange={setIsPopoverOpen}
        modal={modalPopover}
      >
        <PopoverTrigger asChild>
          <Button
            ref={ref}
            {...props}
            onClick={handleTogglePopover}
            className={cn(
              "flex w-full p-1 rounded-md border min-h-10 h-auto items-center justify-between bg-inherit hover:bg-inherit [&_svg]:pointer-events-auto",
              className
            )}
          >
            {selectedValues.length > 0 ? (
              <div className="flex justify-between items-center w-full">
                <div className="flex flex-wrap items-center">
                  {selectedValues.slice(0, maxCount).map((value) => {
                    const option = options.find((o) => o.value === value);
                    const IconComponent = option?.icon;
                    return (
                      <Badge
                        key={value}
                        className={cn(
                          isAnimating ? "animate-bounce" : "",
                          multiSelectVariants({ variant })
                        )}
                        style={{ animationDuration: `${animation}s` }}
                      >
                        {IconComponent && (
                          <IconComponent className="h-4 w-4 mr-2" />
                        )}
                        {option?.label}
                        <XCircleIcon
                          className="ml-2 h-4 w-4 cursor-pointer"
                          onClick={(event) => {
                            event.stopPropagation();
                            toggleOption(value);
                          }}
                        />
                      </Badge>
                    );
                  })}
                  {selectedValues.length > maxCount && (
                    <Badge
                      className={cn(
                        "bg-transparent text-foreground border-foreground/1 hover:bg-transparent",
                        isAnimating ? "animate-bounce" : "",
                        multiSelectVariants({ variant })
                      )}
                      style={{ animationDuration: `${animation}s` }}
                    >
                      {maxCount > 0
                        ? `+ ${selectedValues.length - maxCount} more`
                        : `${selectedValues.length} selected`}
                      <XCircleIcon
                        className="ml-2 h-4 w-4 cursor-pointer"
                        onClick={(event) => {
                          event.stopPropagation();
                          clearExtraOptions();
                        }}
                      />
                    </Badge>
                  )}
                </div>
                <div className="flex items-center justify-between">
                  <XIcon
                    className="h-4 mx-2 cursor-pointer text-muted-foreground"
                    onClick={(event) => {
                      event.stopPropagation();
                      handleClear();
                    }}
                  />
                  <Separator
                    orientation="vertical"
                    className="flex min-h-6 h-full"
                  />
                  <ChevronDownIcon className="h-4 mx-2 cursor-pointer text-muted-foreground" />
                </div>
              </div>
            ) : (
              <div className="flex items-center justify-between w-full mx-auto">
                <span className="text-sm text-muted-foreground mx-3">
                  {placeholder}
                </span>
                <ChevronDownIcon className="h-4 cursor-pointer text-muted-foreground mx-2" />
              </div>
            )}
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className="w-auto p-0"
          align="start"
          onEscapeKeyDown={() => setIsPopoverOpen(false)}
        >
          <Command>
            <CommandInput
              placeholder="Search..."
              onKeyDown={handleInputKeyDown}
            />
            <CommandList>
              <CommandEmpty>No results found.</CommandEmpty>
              <CommandGroup>
                <CommandItem
                  key="all"
                  onSelect={toggleAll}
                  className="cursor-pointer"
                >
                  <div
                    className={cn(
                      "mr-2 flex h-4 w-4 items-center justify-center rounded-sm border border-primary",
                      selectedValues.length === options.length
                        ? "bg-primary text-primary-foreground"
                        : "opacity-50 [&_svg]:invisible"
                    )}
                  >
                    <CheckIcon className="h-4 w-4 text-primary-foreground" />
                  </div>
                  <span>(Select All)</span>
                </CommandItem>
                {options.map((option) => {
                  const isSelected = selectedValues.includes(option.value);
                  return (
                    <CommandItem
                      key={option.value}
                      onSelect={() => toggleOption(option.value)}
                      className="cursor-pointer"
                    >
                      <div
                        className={cn(
                          "mr-2 flex h-4 w-4 items-center justify-center rounded-sm border border-primary",
                          isSelected
                            ? "bg-primary text-primary-foreground"
                            : "opacity-50 [&_svg]:invisible"
                        )}
                      >
                        <CheckIcon className="h-4 w-4 text-primary-foreground" />
                      </div>
                      {option.icon && (
                        <option.icon className="mr-2 h-4 w-4 text-muted-foreground" />
                      )}
                      <span>{option.label}</span>
                    </CommandItem>
                  );
                })}
              </CommandGroup>
              <CommandSeparator />
              <CommandGroup>
                <div className="flex items-center justify-between">
                  {selectedValues.length > 0 && (
                    <>
                      <CommandItem
                        onSelect={handleClear}
                        className="flex-1 justify-center cursor-pointer"
                      >
                        Clear
                      </CommandItem>
                      <Separator
                        orientation="vertical"
                        className="flex min-h-6 h-full"
                      />
                    </>
                  )}
                  <CommandItem
                    onSelect={() => setIsPopoverOpen(false)}
                    className="flex-1 justify-center cursor-pointer max-w-full"
                  >
                    Close
                  </CommandItem>
                </div>
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
        {animation > 0 && selectedValues.length > 0 && (
          <WandSparklesIcon
            className={cn(
              "cursor-pointer my-2 text-foreground bg-background w-3 h-3",
              isAnimating ? "" : "text-muted-foreground"
            )}
            onClick={() => setIsAnimating(!isAnimating)}
          />
        )}
      </Popover>
    );
  }
);

MultiSelect.displayName = "MultiSelect";

import { ParameterValue, Tool, Command } from "@/components/commandly/types/tool";
import { writeClipboard } from "@/components/commandly/utils/clipboard";
import { generateCommand, getToolFlagForms } from "@/components/commandly/utils/generate-command";
import { Button } from "@/components/ui/button";
import { CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";
import { TerminalIcon, CopyIcon, SaveIcon } from "lucide-react";
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { toast } from "sonner";

interface GeneratedCommandProps {
  tool: Tool;
  selectedCommand?: Command | null;
  parameterValues: Record<string, ParameterValue>;
  onSaveCommand?: (command: string) => void;
  /** Position emitted by default: 0 is a parameter's full flag, later positions its aliases. */
  defaultFlagFormIndex?: number;
  children?: ReactNode;
}

interface FlagFormOption {
  index: number;
  label: string;
}

interface GeneratedCommandContextValue {
  generatedCommand: string;
  flagFormIndex: number;
  setFlagFormIndex: (value: number) => void;
  flagFormOptions: FlagFormOption[];
  onCopyCommand: () => void;
  onSaveCommand?: (command: string) => void;
}

const GeneratedCommandContext = createContext<GeneratedCommandContextValue | null>(null);

function useGeneratedCommandContext() {
  const context = useContext(GeneratedCommandContext);

  if (!context) {
    throw new Error("GeneratedCommand compound components must be used within GeneratedCommand.");
  }

  return context;
}

function GeneratedCommandRoot({
  tool,
  selectedCommand: providedCommand,
  parameterValues,
  onSaveCommand,
  defaultFlagFormIndex = 0,
  children,
}: GeneratedCommandProps) {
  const [flagFormIndex, setFlagFormIndex] = useState(defaultFlagFormIndex);

  const flagFormOptions = useMemo<FlagFormOption[]>(
    () => getToolFlagForms(tool).map((label, index) => ({ index, label })),
    [tool],
  );

  const generatedCommand = useMemo(
    () =>
      generateCommand(tool, parameterValues, {
        selectedCommand: providedCommand,
        flagFormIndex,
      }),
    [tool, parameterValues, providedCommand, flagFormIndex],
  );

  const copyCommand = useCallback(() => {
    writeClipboard(generatedCommand).then(
      () => toast("Command copied!"),
      () => toast.error("Copy failed"),
    );
  }, [generatedCommand]);

  const contextValue = useMemo(
    () => ({
      generatedCommand,
      flagFormIndex,
      setFlagFormIndex,
      flagFormOptions,
      onCopyCommand: copyCommand,
      onSaveCommand,
    }),
    [generatedCommand, flagFormIndex, flagFormOptions, copyCommand, onSaveCommand],
  );

  return (
    <GeneratedCommandContext.Provider value={contextValue}>
      {generatedCommand ? (
        (children ?? (
          <div className="min-w-0 space-y-4">
            <GeneratedCommandOutput />
            <GeneratedCommandActions />
          </div>
        ))
      ) : (
        <GeneratedCommandEmptyState />
      )}
    </GeneratedCommandContext.Provider>
  );
}

function GeneratedCommandToolbar({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn("flex flex-wrap items-center justify-end gap-2", className)}
      {...props}
    />
  );
}

function GeneratedCommandHeader({
  children,
  className,
  ...props
}: ComponentProps<typeof CardHeader>) {
  return (
    <CardHeader
      className={cn("flex flex-row items-center justify-between gap-3 space-y-0", className)}
      {...props}
    >
      <CardTitle className="flex items-center gap-2">
        <TerminalIcon className="h-5 w-5" />
        Generated Command
      </CardTitle>
      {children}
    </CardHeader>
  );
}

function GeneratedCommandFlagFormPreference({
  className,
  ...props
}: Omit<ComponentProps<typeof SelectTrigger>, "value" | "onValueChange">) {
  const { flagFormIndex, setFlagFormIndex, flagFormOptions } = useGeneratedCommandContext();

  if (flagFormOptions.length < 2) return null;

  return (
    <div className="flex shrink-0 items-center gap-2">
      <Label className="font-mono text-xs tracking-[0.12em] text-muted-foreground uppercase">
        Flag style
      </Label>
      <Select
        value={String(flagFormIndex)}
        onValueChange={(value) => setFlagFormIndex(Number(value))}
      >
        <SelectTrigger
          className={cn("h-8 w-36", className)}
          aria-label="Flag style"
          {...props}
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {flagFormOptions.map((option) => (
            <SelectItem
              key={option.index}
              value={String(option.index)}
            >
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

function GeneratedCommandOutput({ className, ...props }: ComponentProps<"div">) {
  const { generatedCommand } = useGeneratedCommandContext();

  return (
    <div
      className={cn("overflow-x-auto rounded bg-muted p-4 font-mono text-sm", className)}
      {...props}
    >
      <div className="min-w-max whitespace-nowrap">{generatedCommand}</div>
    </div>
  );
}

function GeneratedCommandActions({ className, ...props }: ComponentProps<"div">) {
  const { generatedCommand, onCopyCommand, onSaveCommand } = useGeneratedCommandContext();

  return (
    <div
      className={cn("flex flex-col gap-2 sm:flex-row", className)}
      {...props}
    >
      <Button
        onClick={onCopyCommand}
        variant="outline"
        className="w-full sm:flex-1"
      >
        <CopyIcon className="mr-2 h-4 w-4" />
        Copy Command
      </Button>
      {onSaveCommand && (
        <Button
          onClick={() => onSaveCommand(generatedCommand)}
          variant="outline"
          className="w-full sm:flex-1"
        >
          <SaveIcon className="mr-2 h-4 w-4" />
          Save Command
        </Button>
      )}
    </div>
  );
}

function GeneratedCommandEmptyState() {
  return (
    <div className="py-8 text-center">
      <TerminalIcon className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
      <p className="text-muted-foreground">Configure parameters to generate the command.</p>
    </div>
  );
}

export const GeneratedCommand = Object.assign(GeneratedCommandRoot, {
  Header: GeneratedCommandHeader,
  Toolbar: GeneratedCommandToolbar,
  FlagFormPreference: GeneratedCommandFlagFormPreference,
  Output: GeneratedCommandOutput,
  Actions: GeneratedCommandActions,
  EmptyState: GeneratedCommandEmptyState,
});

import { JsonTree } from "@/components/commandly/json-tree";
import { Tool } from "@/components/commandly/types/tool";
import { writeClipboard } from "@/components/commandly/utils/clipboard";
import { collapseUnchanged, diffLines, type DiffLineType } from "@/components/commandly/utils/diff";
import { exportToStructuredJSON } from "@/components/commandly/utils/tool-file";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardAction, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { CopyIcon, Edit2Icon, XIcon } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";

interface JsonOutputProps {
  tool: Tool;
  originalTool?: Tool;
  onApply?: (tool: Tool) => void;
}

/** The gutter marker for each kind of diff line. */
const DIFF_MARKER: Record<DiffLineType, string> = { same: "  ", added: "+ ", removed: "- " };

/** The row tones for each kind of diff line. */
const DIFF_TONE: Record<DiffLineType, string> = {
  same: "text-foreground/80",
  added: "bg-green-500/10 text-green-700 dark:text-green-400",
  removed: "bg-red-500/10 text-red-700 dark:text-red-400",
};

export function JsonOutput({ tool, originalTool, onApply }: JsonOutputProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState("");
  const [showDiff, setShowDiff] = useState(true);

  const jsonString = useMemo(() => JSON.stringify(exportToStructuredJSON(tool), null, 2), [tool]);
  const originalJsonString = useMemo(
    () =>
      originalTool ? JSON.stringify(exportToStructuredJSON(originalTool), null, 2) : undefined,
    [originalTool],
  );
  const data = useMemo(() => JSON.parse(jsonString) as unknown, [jsonString]);

  const diff = useMemo(() => {
    if (!originalJsonString || originalJsonString === jsonString) return null;
    return collapseUnchanged(diffLines(originalJsonString, jsonString));
  }, [originalJsonString, jsonString]);

  const diffStats = useMemo(() => {
    if (!diff) return null;
    const added = diff.filter((l) => l.type === "added").length;
    const removed = diff.filter((l) => l.type === "removed").length;
    return { added, removed };
  }, [diff]);

  const handleEditToggle = () => {
    setEditValue(jsonString);
    setIsEditing(true);
  };

  const handleApply = () => {
    if (!onApply) return;
    try {
      const parsed = JSON.parse(editValue) as Tool;
      onApply(parsed);
      setIsEditing(false);
    } catch {
      toast.error("Invalid JSON", { description: "Please fix the JSON before applying." });
    }
  };

  const handleCancel = () => {
    setIsEditing(false);
    setEditValue("");
  };

  return (
    <Card className="max-w-full">
      <CardHeader className="gap-4">
        <CardTitle className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:items-center">
            <span className="text-sm text-muted-foreground">
              Structured JSON output for this tool.
            </span>
          </div>
        </CardTitle>
        <div className="flex shrink-0 items-center gap-3 self-start sm:self-auto">
          {onApply && !isEditing && (
            <CardAction
              className="rounded-md"
              onClick={handleEditToggle}
            >
              <Edit2Icon className="h-4 w-4 dark:stroke-primary" />
            </CardAction>
          )}
          {onApply && isEditing && (
            <CardAction
              className="rounded-md"
              onClick={handleCancel}
            >
              <XIcon className="h-4 w-4 dark:stroke-primary" />
            </CardAction>
          )}
          <CardAction
            className="rounded-md"
            onClick={() => {
              writeClipboard(jsonString).then(
                () => toast("Copied!"),
                () => toast.error("Copy failed"),
              );
            }}
          >
            <CopyIcon className="h-4 w-4 dark:stroke-primary" />
          </CardAction>
        </div>
      </CardHeader>
      <CardContent>
        {diffStats && !isEditing && (
          <div className="mb-2 flex flex-wrap items-center gap-2">
            {diffStats.added > 0 && (
              <Badge
                variant="outline"
                className="border-green-500/40 bg-green-500/10 text-green-600 dark:text-green-400"
              >
                +{diffStats.added} added
              </Badge>
            )}
            {diffStats.removed > 0 && (
              <Badge
                variant="outline"
                className="border-red-500/40 bg-red-500/10 text-red-600 dark:text-red-400"
              >
                -{diffStats.removed} removed
              </Badge>
            )}
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-xs sm:ml-auto"
              onClick={() => setShowDiff((v) => !v)}
            >
              {showDiff ? "Full view" : "Diff view"}
            </Button>
          </div>
        )}
        {isEditing ? (
          <div className="flex flex-col gap-2">
            <ScrollArea
              className="max-w-full *:data-radix-scroll-area-viewport:max-h-[calc(100vh-360px)]"
              type="hover"
            >
              <Textarea
                className="min-h-80 font-mono text-sm sm:min-h-[calc(100vh-400px)]"
                value={editValue}
                onChange={(e) => setEditValue(e.target.value)}
                spellCheck={false}
              />
              <ScrollBar orientation="vertical" />
              <ScrollBar orientation="horizontal" />
            </ScrollArea>
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handleCancel}
              >
                Cancel
              </Button>
              <Button
                size="sm"
                onClick={handleApply}
              >
                Apply
              </Button>
            </div>
          </div>
        ) : diff && showDiff ? (
          <ScrollArea
            className="max-w-full *:data-radix-scroll-area-viewport:max-h-[calc(100vh-320px)]"
            type="hover"
          >
            <pre className="w-fit min-w-full rounded-md font-mono text-sm whitespace-pre">
              {diff.map((row, idx) =>
                row.type === "gap" ? (
                  <div
                    key={idx}
                    className="px-1 text-muted-foreground/70"
                  >
                    … {row.count} unchanged {row.count === 1 ? "line" : "lines"}
                  </div>
                ) : (
                  <div
                    key={idx}
                    className={cn("px-1", DIFF_TONE[row.type])}
                  >
                    <span className="opacity-50 select-none">{DIFF_MARKER[row.type]}</span>
                    {row.text}
                  </div>
                ),
              )}
            </pre>
            <ScrollBar orientation="vertical" />
            <ScrollBar orientation="horizontal" />
          </ScrollArea>
        ) : (
          <JsonTree data={data} />
        )}
      </CardContent>
    </Card>
  );
}

import { writeClipboard } from "@/components/commandly/utils/clipboard";
import {
  allBranches,
  branchesToDepth,
  childPath,
  copyText,
  countLabel,
  entries,
  isBranch,
  primitiveText,
  searchJson,
  type JsonValueType,
  typeOf,
  within,
} from "@/components/commandly/utils/json-tree";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  ChevronDownIcon,
  ChevronRightIcon,
  ChevronsDownUpIcon,
  ChevronsUpDownIcon,
  ChevronUpIcon,
  CopyIcon,
  Link2Icon,
  SearchIcon,
} from "lucide-react";
import type { KeyboardEvent as ReactKeyboardEvent, ReactNode } from "react";
import { useCallback, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";

const INDENT = 14;

const VALUE_CLASS: Record<JsonValueType, string> = {
  object: "text-sky-600 dark:text-sky-400",
  array: "text-sky-600 dark:text-sky-400",
  string: "text-emerald-600 dark:text-emerald-400",
  number: "text-amber-600 dark:text-amber-400",
  boolean: "text-violet-600 dark:text-violet-400",
  null: "text-muted-foreground italic",
  other: "text-muted-foreground",
};

function Highlight({ text, needle, current }: { text: string; needle: string; current: boolean }) {
  if (!needle) return <>{text}</>;
  const lower = text.toLowerCase();
  const parts: ReactNode[] = [];
  let from = 0;
  let at = lower.indexOf(needle);
  while (at !== -1) {
    if (at > from) parts.push(text.slice(from, at));
    parts.push(
      <mark
        key={at}
        className={cn(
          "rounded-[2px] bg-yellow-300/60 text-inherit dark:bg-yellow-500/40",
          current && "bg-orange-400/70 dark:bg-orange-500/60",
        )}
      >
        {text.slice(at, at + needle.length)}
      </mark>,
    );
    from = at + needle.length;
    at = lower.indexOf(needle, from);
  }
  if (from < text.length) parts.push(text.slice(from));
  return <>{parts}</>;
}

type TreeRow = {
  id: string;
  kind: "node" | "more";
  level: number;
  name: string | number | null;
  value: unknown;
  type: JsonValueType;
  count: number;
  open: boolean;
  parent: string | null;
  posinset: number;
  setsize: number;
  hidden?: number;
};

export interface JsonTreeProps {
  data: unknown;
  rootName?: string;
  defaultExpandDepth?: number;
  pageSize?: number;
  className?: string;
}

function IconAction({
  label,
  onClick,
  disabled,
  tabIndex,
  children,
}: {
  label: string;
  onClick: () => void;
  disabled?: boolean;
  tabIndex?: number;
  children: ReactNode;
}) {
  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-xs"
      aria-label={label}
      title={label}
      disabled={disabled}
      tabIndex={tabIndex}
      className="text-muted-foreground"
      onClick={(event) => {
        event.stopPropagation();
        onClick();
      }}
    >
      {children}
    </Button>
  );
}

export function JsonTree({
  data,
  rootName = "root",
  defaultExpandDepth = 2,
  pageSize = 50,
  className,
}: JsonTreeProps) {
  const treeId = useId();
  const searchRef = useRef<HTMLInputElement>(null);
  const rowRefs = useRef(new Map<string, HTMLDivElement>());

  const [expanded, setExpanded] = useState<string[]>(() =>
    branchesToDepth(data, rootName, defaultExpandDepth),
  );
  const base = useMemo(() => new Set(expanded), [expanded]);

  const [query, setQuery] = useState("");
  const needle = query.trim().toLowerCase();
  const search = useMemo(
    () => (needle ? searchJson(data, rootName, needle) : null),
    [data, needle, rootName],
  );
  const [closedWhileSearching, setClosedWhileSearching] = useState<{
    needle: string;
    ids: Set<string>;
  }>({ needle: "", ids: new Set<string>() });
  const closed = closedWhileSearching.needle === needle ? closedWhileSearching.ids : null;
  const [matchIndex, setMatchIndex] = useState(0);
  const matches = search?.matches ?? [];
  const matchCount = matches.length;
  const matchSet = useMemo(() => new Set(search?.matches ?? []), [search]);
  const currentMatch = matchCount ? matches[Math.min(matchIndex, matchCount - 1)] : null;

  const isOpen = useCallback(
    (id: string) => (search?.ancestors.has(id) ? !closed?.has(id) : base.has(id)),
    [base, closed, search],
  );

  const [pages, setPages] = useState<Record<string, number>>({});
  const limitOf = useCallback(
    (id: string) => Math.max((pages[id] ?? 1) * pageSize, search?.needed.get(id) ?? 0),
    [pageSize, pages, search],
  );

  const rows = useMemo(() => {
    const out: TreeRow[] = [];
    const visit = (
      value: unknown,
      id: string,
      name: string | number | null,
      level: number,
      parent: string | null,
      posinset: number,
      setsize: number,
    ) => {
      const type = typeOf(value);
      const list = isBranch(type) ? entries(value) : [];
      const open = isBranch(type) && isOpen(id);
      out.push({
        id,
        kind: "node",
        level,
        name,
        value,
        type,
        count: list.length,
        open,
        parent,
        posinset,
        setsize,
      });
      if (!open) return;
      const shown = list.slice(0, limitOf(id));
      const hidden = list.length - shown.length;
      const size = shown.length + (hidden > 0 ? 1 : 0);
      shown.forEach(([key, child], index) =>
        visit(child, childPath(id, key), key, level + 1, id, index + 1, size),
      );
      if (hidden > 0) {
        out.push({
          id: `${id}::more`,
          kind: "more",
          level: level + 1,
          name: null,
          value: null,
          type: "other",
          count: 0,
          open: false,
          parent: id,
          posinset: size,
          setsize: size,
          hidden,
        });
      }
    };
    visit(data, rootName, null, 1, null, 1, 1);
    return out;
  }, [data, isOpen, limitOf, rootName]);

  const [activeRaw, setActiveRaw] = useState(rootName);
  const active = useMemo(() => {
    if (rows.some((row) => row.id === activeRaw)) return activeRaw;
    let best = rootName;
    for (const row of rows) {
      if (row.kind === "node" && within(row.id, activeRaw) && row.id.length > best.length) {
        best = row.id;
      }
    }
    return best;
  }, [activeRaw, rootName, rows]);
  const activeIndex = Math.max(
    0,
    rows.findIndex((row) => row.id === active),
  );
  const activeRow = rows[activeIndex];

  const pendingFocus = useRef(false);
  const pendingReveal = useRef(false);

  useLayoutEffect(() => {
    if (pendingFocus.current) {
      pendingFocus.current = false;
      rowRefs.current.get(active)?.focus({ preventScroll: true });
    }
    if (pendingReveal.current) {
      pendingReveal.current = false;
      rowRefs.current.get(active)?.scrollIntoView({ block: "nearest" });
    }
  }, [active, rows]);

  const moveTo = (id: string, focus = true, reveal = true) => {
    if (id === activeRaw) {
      if (focus) rowRefs.current.get(id)?.focus({ preventScroll: true });
      if (reveal) rowRefs.current.get(id)?.scrollIntoView({ block: "nearest" });
      return;
    }
    pendingFocus.current = focus;
    pendingReveal.current = reveal;
    setActiveRaw(id);
  };

  // Reveal the first match once the search has recomputed for the new query.
  const revealedFor = useRef<string | null>(null);
  useLayoutEffect(() => {
    if (revealedFor.current === needle) return;
    revealedFor.current = needle;
    const first = search?.matches[0];
    if (!first) return;
    pendingReveal.current = true;
    setActiveRaw(first);
  }, [needle, search]);

  const toggle = (id: string, next?: boolean) => {
    const open = isOpen(id);
    const want = next ?? !open;
    if (want === open) return;
    if (search?.ancestors.has(id)) {
      const ids = new Set(closed ?? []);
      if (want) ids.delete(id);
      else ids.add(id);
      setClosedWhileSearching({ needle, ids });
      if (want && !base.has(id)) setExpanded([...base, id]);
      return;
    }
    setExpanded(want ? [...base, id] : [...base].filter((item) => item !== id));
  };

  const expandAll = () => {
    setExpanded(allBranches(data, rootName));
    setClosedWhileSearching({ needle, ids: new Set<string>() });
    setPages({});
    moveTo(active, false);
  };

  const collapseAll = () => {
    setExpanded(isBranch(typeOf(data)) ? [rootName] : []);
    setClosedWhileSearching({
      needle,
      ids: new Set([...(search?.ancestors ?? [])].filter((id) => id !== rootName)),
    });
    setPages({});
    moveTo(rootName, false, false);
  };

  const showMore = (parent: string) =>
    setPages((current) => ({ ...current, [parent]: Math.ceil(limitOf(parent) / pageSize) + 1 }));

  const copy = (row: TreeRow, kind: "value" | "path") => {
    const text = kind === "path" ? row.id : copyText(row.value, row.type);
    writeClipboard(text).then(
      () => toast(kind === "path" ? "Copied path" : "Copied value"),
      () => toast.error("Copy failed"),
    );
  };

  const stepMatch = (step: number) => {
    if (!matchCount) return;
    const next =
      (((Math.min(matchIndex, matchCount - 1) + step) % matchCount) + matchCount) % matchCount;
    setMatchIndex(next);
    moveTo(matches[next], false);
  };

  const onQuery = (next: string) => {
    setQuery(next);
    setMatchIndex(0);
  };

  const onSearchKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      event.preventDefault();
      stepMatch(event.shiftKey ? -1 : 1);
    } else if (event.key === "Escape" && query) {
      event.preventDefault();
      event.stopPropagation();
      onQuery("");
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      moveTo(active);
    }
  };

  const onTreeKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    const row = rows[activeIndex];
    if (!row || event.altKey) return;
    const mod = event.metaKey || event.ctrlKey;
    if (mod && event.key.toLowerCase() === "c") {
      if (row.kind === "node" && !window.getSelection()?.toString()) {
        event.preventDefault();
        copy(row, event.shiftKey ? "path" : "value");
      }
      return;
    }
    if (mod) return;
    const go = (index: number) => {
      event.preventDefault();
      const target = rows[Math.max(0, Math.min(rows.length - 1, index))];
      if (target) moveTo(target.id);
    };
    switch (event.key) {
      case "ArrowDown":
        go(activeIndex + 1);
        break;
      case "ArrowUp":
        go(activeIndex - 1);
        break;
      case "Home":
        go(0);
        break;
      case "End":
        go(rows.length - 1);
        break;
      case "ArrowRight":
        event.preventDefault();
        if (row.kind === "node" && isBranch(row.type)) {
          if (!row.open) toggle(row.id, true);
          else if (row.count) go(activeIndex + 1);
        }
        break;
      case "ArrowLeft":
        event.preventDefault();
        if (row.kind === "node" && row.open) toggle(row.id, false);
        else if (row.parent) moveTo(row.parent);
        break;
      case "Enter":
      case " ":
        event.preventDefault();
        if (row.kind === "more") showMore(row.parent ?? rootName);
        else if (isBranch(row.type)) toggle(row.id);
        break;
      case "/":
        event.preventDefault();
        searchRef.current?.focus();
        searchRef.current?.select();
        break;
      default:
        break;
    }
  };

  const describe = (row: TreeRow) => {
    const name = row.name === null ? rootName : String(row.name);
    if (row.kind === "more") {
      return `Show ${Math.min(pageSize, row.hidden ?? 0)} more, ${row.hidden} hidden`;
    }
    if (isBranch(row.type)) return `${name}, ${row.type}, ${countLabel(row.type, row.count)}`;
    const text = primitiveText(row.value, row.type);
    return `${name}: ${text.length > 60 ? `${text.slice(0, 60)}…` : text}`;
  };

  const pathOf = (row: TreeRow) => (row.kind === "node" ? row.id : (row.parent ?? ""));

  return (
    <div className={cn("flex flex-col gap-3", className)}>
      <div className="flex flex-wrap items-center gap-2">
        <label className="relative flex h-8 min-w-0 flex-1 items-center">
          <SearchIcon
            className="pointer-events-none absolute left-2 size-3.5 text-muted-foreground"
            aria-hidden="true"
          />
          <input
            ref={searchRef}
            type="search"
            value={query}
            onChange={(event) => onQuery(event.target.value)}
            onKeyDown={onSearchKeyDown}
            placeholder="Search keys and values"
            aria-label="Search JSON"
            aria-controls={treeId}
            spellCheck={false}
            autoComplete="off"
            className={cn(
              "h-8 w-full rounded-lg border border-input bg-transparent pr-16 pl-7 text-sm outline-none",
              "placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50",
              "[&::-webkit-search-cancel-button]:hidden",
            )}
          />
          {needle ? (
            <span className="absolute right-1 flex items-center gap-0.5">
              <span
                className="px-1 text-xs text-muted-foreground tabular-nums"
                aria-live="polite"
              >
                {matchCount ? `${Math.min(matchIndex, matchCount - 1) + 1}/${matchCount}` : "0/0"}
              </span>
              <IconAction
                label="Previous match"
                disabled={!matchCount}
                onClick={() => stepMatch(-1)}
              >
                <ChevronUpIcon />
              </IconAction>
              <IconAction
                label="Next match"
                disabled={!matchCount}
                onClick={() => stepMatch(1)}
              >
                <ChevronDownIcon />
              </IconAction>
            </span>
          ) : null}
        </label>
        <div className="flex shrink-0 items-center gap-1">
          <IconAction
            label="Expand all"
            onClick={expandAll}
          >
            <ChevronsUpDownIcon />
          </IconAction>
          <IconAction
            label="Collapse all"
            onClick={collapseAll}
          >
            <ChevronsDownUpIcon />
          </IconAction>
        </div>
      </div>

      <div className="max-h-[calc(100vh-420px)] overflow-auto rounded-lg border">
        <div
          id={treeId}
          role="tree"
          aria-label="Tool JSON"
          onKeyDown={onTreeKeyDown}
          className="w-fit min-w-full py-1 outline-none"
        >
          {rows.map((row) => {
            const isActive = row.id === active;
            const branch = isBranch(row.type);
            const mark = search && row.kind === "node" && matchSet.has(row.id) ? needle : "";
            const current = row.id === currentMatch;
            return (
              <div
                key={row.id}
                ref={(node) => {
                  if (node) rowRefs.current.set(row.id, node);
                  else rowRefs.current.delete(row.id);
                }}
                role="treeitem"
                tabIndex={isActive ? 0 : -1}
                aria-level={row.level}
                aria-posinset={row.posinset}
                aria-setsize={row.setsize}
                aria-expanded={row.kind === "node" && branch ? row.open : undefined}
                aria-selected={isActive}
                aria-label={describe(row)}
                className={cn(
                  "group relative flex h-7.5 items-center gap-1 pr-1 text-sm outline-none",
                  "focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:ring-inset",
                  isActive ? "bg-accent/60" : "hover:bg-muted/60",
                )}
                style={{ paddingLeft: (row.level - 1) * INDENT + 4 }}
                onFocus={(event) => {
                  if (event.target === event.currentTarget && row.id !== active) {
                    setActiveRaw(row.id);
                  }
                }}
                onClick={() => {
                  if (row.kind === "more") {
                    showMore(row.parent ?? rootName);
                    moveTo(row.id);
                    return;
                  }
                  if (branch) toggle(row.id);
                  moveTo(row.id);
                }}
              >
                {row.kind === "more" ? (
                  <span className="flex items-center gap-2 text-muted-foreground">
                    <span>Show {Math.min(pageSize, row.hidden ?? 0)} more</span>
                    <span className="text-xs">{row.hidden} hidden</span>
                  </span>
                ) : (
                  <>
                    <span className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
                      {branch ? (
                        <ChevronRightIcon
                          className={cn("size-3.5 transition-transform", row.open && "rotate-90")}
                          aria-hidden="true"
                        />
                      ) : null}
                    </span>
                    <span
                      className={cn(
                        "shrink-0 font-medium",
                        typeof row.name === "number" && "text-muted-foreground",
                      )}
                    >
                      {row.name === null ? (
                        rootName
                      ) : typeof row.name === "number" ? (
                        row.name
                      ) : (
                        <Highlight
                          text={row.name}
                          needle={mark}
                          current={current}
                        />
                      )}
                    </span>
                    <span
                      className="text-muted-foreground"
                      aria-hidden="true"
                    >
                      {row.name === null && branch ? "" : ":"}
                    </span>
                    {branch ? (
                      <span className="flex min-w-0 items-baseline gap-2">
                        {!row.open ? (
                          <span className="truncate text-muted-foreground">
                            {row.type === "array"
                              ? "[…]"
                              : `{ ${entries(row.value)
                                  .slice(0, 3)
                                  .map(([key]) => key)
                                  .join(", ")}${row.count > 3 ? ", …" : ""} }`}
                          </span>
                        ) : null}
                        <span className="shrink-0 text-xs text-muted-foreground">
                          {countLabel(row.type, row.count)}
                        </span>
                      </span>
                    ) : (
                      <span
                        className={cn("min-w-0 truncate font-mono", VALUE_CLASS[row.type])}
                        title={
                          row.type === "string" && (row.value as string).length > 40
                            ? (row.value as string)
                            : undefined
                        }
                      >
                        {row.type === "string" ? (
                          <>
                            &quot;
                            <Highlight
                              text={row.value as string}
                              needle={mark}
                              current={current}
                            />
                            &quot;
                          </>
                        ) : (
                          <Highlight
                            text={primitiveText(row.value, row.type)}
                            needle={mark}
                            current={current}
                          />
                        )}
                      </span>
                    )}
                    <span
                      className={cn(
                        "ml-auto flex shrink-0 items-center gap-0.5",
                        isActive
                          ? "opacity-100"
                          : "opacity-0 group-focus-within:opacity-100 group-hover:opacity-100",
                      )}
                    >
                      <IconAction
                        label="Copy value"
                        tabIndex={-1}
                        onClick={() => copy(row, "value")}
                      >
                        <CopyIcon />
                      </IconAction>
                      <IconAction
                        label="Copy path"
                        tabIndex={-1}
                        onClick={() => copy(row, "path")}
                      >
                        <Link2Icon />
                      </IconAction>
                    </span>
                  </>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {activeRow ? (
        <div className="flex items-center gap-2 rounded-lg border bg-muted/40 px-2 py-1.5">
          <code
            className="min-w-0 flex-1 truncate font-mono text-xs text-muted-foreground"
            title={pathOf(activeRow)}
          >
            {pathOf(activeRow)}
          </code>
          <span className="shrink-0 text-xs text-muted-foreground">
            {activeRow.kind === "node"
              ? isBranch(activeRow.type)
                ? `${activeRow.type}, ${countLabel(activeRow.type, activeRow.count)}`
                : activeRow.type
              : "page"}
          </span>
          {activeRow.kind === "node" ? (
            <IconAction
              label="Copy path"
              tabIndex={-1}
              onClick={() => copy(activeRow, "path")}
            >
              <CopyIcon />
            </IconAction>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

import {
  ParameterRenderContext,
  ParameterRendererEntry,
} from "@/components/commandly/types/renderer";
import { Command, ParameterValue, Tool } from "@/components/commandly/types/tool";
import { getFlagForms } from "@/components/commandly/utils/generate-command";
import {
  excludedParameters,
  getDefaultCommand,
  requiredParameterKeys,
  resolveApplicableParameters,
  resolveExclusionGroups,
} from "@/components/commandly/utils/tool";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command as UICommand,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { MultiSelect } from "@/components/ui/multi-select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Switch } from "@/components/ui/switch";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { CheckIcon, ChevronsUpDownIcon, InfoIcon, PlusIcon, XIcon } from "lucide-react";
import React, { useMemo } from "react";

interface ParameterLabelProps {
  name: string;
  flags?: string[];
  isRequired?: boolean;
  recursive?: boolean;
  excludedBy?: string;
  description?: string;
  className?: string;
  children?: React.ReactNode;
}

function ParameterLabel({
  name,
  flags,
  isRequired,
  recursive,
  excludedBy,
  description,
  className,
  children,
}: ParameterLabelProps) {
  return (
    <Label className={className}>
      {name}
      {!!flags?.length && <span className="ml-1 text-muted-foreground">({flags.join(", ")})</span>}
      {isRequired && <span className="ml-1 text-destructive">*</span>}
      {description?.trim() && (
        <Tooltip>
          <TooltipTrigger>
            <InfoIcon className="h-3.5 w-3.5" />
          </TooltipTrigger>
          <TooltipContent>
            <span>{description}</span>
          </TooltipContent>
        </Tooltip>
      )}
      {children}
      {recursive && (
        <Badge
          variant="outline"
          className="ml-2 text-xs"
        >
          recursive
        </Badge>
      )}
      {excludedBy && (
        <Badge
          variant="outline"
          className="ml-2 text-xs"
        >
          excluded by {excludedBy}
        </Badge>
      )}
    </Label>
  );
}

function FlagInput({
  parameter,
  flags,
  value,
  onUpdate,
  isRequired,
  excludedBy,
}: ParameterRenderContext) {
  return (
    <div className="flex items-center space-x-2">
      <Switch
        checked={value === "true" || value === true}
        onCheckedChange={onUpdate}
        disabled={!!excludedBy}
      />
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.displayName}
        flags={flags}
        isRequired={isRequired}
        recursive={parameter.recursive}
        excludedBy={excludedBy}
        description={parameter.description}
      />
    </div>
  );
}

function OptionEnumInput({
  parameter,
  flags,
  value,
  onUpdate,
  isRequired,
  excludedBy,
}: ParameterRenderContext) {
  const [open, setOpen] = React.useState(false);
  const separator = parameter.enum?.separator || ",";
  const options =
    parameter.enum?.values?.map((e) => ({
      value: e.value,
      label: e.displayName || e.value,
    })) ?? [];

  const label = (
    <ParameterLabel
      className="select-auto"
      name={parameter.displayName}
      flags={flags}
      isRequired={isRequired}
      recursive={parameter.recursive}
      excludedBy={excludedBy}
      description={parameter.description}
    />
  );

  if (parameter.enum?.allowMultiple) {
    const selected = Array.isArray(value)
      ? (value as string[]).filter(Boolean)
      : value
        ? (value as string).split(separator).filter(Boolean)
        : [];
    return (
      <div className="space-y-2">
        {label}
        <MultiSelect
          options={options}
          defaultValue={selected}
          onValueChange={(vals) => onUpdate(vals.join(separator))}
          placeholder="Select options"
          disabled={!!excludedBy}
        />
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {label}
      <Popover
        open={open}
        onOpenChange={setOpen}
      >
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            role="combobox"
            aria-expanded={open}
            className="w-full justify-between font-normal"
            disabled={!!excludedBy}
          >
            {options.find((o) => o.value === value)?.label ?? "Select an option"}
            <ChevronsUpDownIcon className="opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className="w-[--radix-popover-trigger-width] p-0"
          align="start"
        >
          <UICommand>
            <CommandInput placeholder="Search..." />
            <CommandList>
              <CommandEmpty>No option found.</CommandEmpty>
              <CommandGroup>
                {options.map((option) => (
                  <CommandItem
                    key={option.value}
                    value={option.value}
                    onSelect={(currentValue) => {
                      onUpdate(currentValue === value ? "" : currentValue);
                      setOpen(false);
                    }}
                  >
                    {option.label}
                    <CheckIcon
                      className={cn(
                        "ml-auto",
                        value === option.value ? "opacity-100" : "opacity-0",
                      )}
                    />
                  </CommandItem>
                ))}
              </CommandGroup>
            </CommandList>
          </UICommand>
        </PopoverContent>
      </Popover>
    </div>
  );
}

function OptionBooleanInput({
  parameter,
  flags,
  value,
  onUpdate,
  isRequired,
  excludedBy,
}: ParameterRenderContext) {
  return (
    <div className="flex items-center space-x-2">
      <Switch
        checked={value === "true" || value === true}
        onCheckedChange={(checked) => onUpdate(checked.toString())}
        disabled={!!excludedBy}
      />
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.displayName}
        flags={flags}
        isRequired={isRequired}
        recursive={parameter.recursive}
        excludedBy={excludedBy}
        description={parameter.description}
      />
    </div>
  );
}

function OptionTextInput({
  parameter,
  flags,
  value,
  onUpdate,
  isRequired,
  excludedBy,
}: ParameterRenderContext) {
  return (
    <div className="space-y-2">
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.displayName}
        flags={flags}
        isRequired={isRequired}
        recursive={parameter.recursive}
        excludedBy={excludedBy}
        description={parameter.description}
